\title{Onion Creek Flashiness Analysis: Sequence-to-One LSTM Modeling of Daily Stream Discharge from a Seven-Day Precipitation Window (2015--2020)}

% --- Author Information (Please Edit) ---
\author[1]{Your Name\corref{cor1}}
